let c = ContinuousClock()
let start = c.now
let later = start.advanced(by: .seconds(5))
print(start.duration(to: later))

let c = SuspendingClock()
let start = c.now
try await c.sleep(for: .milliseconds(5))
let d = start.duration(to: c.now)
print(d >= .milliseconds(5))

